    goldCaseIds: z.array(z.string().trim().min(1)).min(1),
    adversarialCaseIds: z.array(z.string().trim().min(1)).min(1),
    e2eScenarioIds: z.array(z.string().trim().min(1)).min(1),
    costEvalIds: z.array(z.string().trim().min(1)).min(1),
