   111	export function calculateCoverageSeries(input: {
   112	  schedule: readonly DebtServiceRow[];
   113	  scenarios: Array<{name: string; cfadsByPeriod: Record<number, Decimal.Value>}>;
   114	}) {
   115	  return input.scenarios.map((scenario) => {
   116	    const periods = input.schedule.map((row) => {
   117	      const cfads = scenario.cfadsByPeriod[row.period];
   118	      if (cfads === undefined) return {period: row.period, cfads: null, debtService: row.debtService, dscr: null};
   119	      const service = d(row.debtService);
   120	      return {period: row.period, cfads: canonical(d(cfads)), debtService: row.debtService, dscr: service.gt(0) ? canonical(d(cfads).div(service)) : null};
   121	    });
   122	    const computable = periods.filter((period): period is typeof period & {dscr: string} => period.dscr !== null);
   123	    const minimum = computable.length
   124	      ? computable.reduce((lowest, period) => d(period.dscr).lt(lowest.dscr) ? period : lowest)
   125	      : null;
   126	    return {name: scenario.name, periods, minimumDscr: minimum?.dscr ?? null, criticalPeriod: minimum?.period ?? null};
   127	  });
   128	}
