   130	export function calculateCovenantHeadroom(input: {actual: Decimal.Value; limit: Decimal.Value; direction: "maximum" | "minimum"}) {
   131	  const actual = d(input.actual);
   132	  const limit = d(input.limit);
   133	  const absolute = input.direction === "maximum" ? limit.minus(actual) : actual.minus(limit);
   134	  const percentage = limit.eq(0) ? null : absolute.div(limit);
   135	  return {absolute: canonical(absolute), percentage: percentage === null ? null : canonical(percentage), passes: absolute.gte(0)};
