   138	export function maturityConcentration(input: {existing: Record<string, Decimal.Value>; proposed: Record<string, Decimal.Value>}) {
   139	  const periods = [...new Set([...Object.keys(input.existing), ...Object.keys(input.proposed)])].sort();
   140	  const rows = periods.map((period) => ({
   141	    period,
   142	    existing: canonical(d(input.existing[period] ?? 0)),
   143	    proposed: canonical(d(input.proposed[period] ?? 0)),
   144	    consolidated: canonical(d(input.existing[period] ?? 0).plus(input.proposed[period] ?? 0)),
   145	  }));
   146	  const total = rows.reduce((sum, row) => sum.plus(row.consolidated), new Decimal(0));
   147	  return {
   148	    rows: rows.map((row) => ({...row, share: total.gt(0) ? canonical(d(row.consolidated).div(total)) : "0"})),
   149	    total: canonical(total),
   150	    peak: rows.length ? rows.reduce((highest, row) => d(row.consolidated).gt(highest.consolidated) ? row : highest) : null,
   151	  };
   152	}
