   262	export function reconcileInterestExpense(components: readonly InterestExpenseComponent[]) {
   263	  const rows = components.map((component) => {
   264	    const calculated = decimal(component.calculated);
   265	    const accounting = decimal(component.accounting);
   266	    return {
