   281	export type LiquidityPeriod = {
   282	  period: string;
   283	  openingCash: NumericInput;
   284	  cfads: NumericInput;
   285	  contractedSources?: NumericInput;
   286	  principal: NumericInput;
   287	  interest: NumericInput;
   288	  leases?: NumericInput;
   289	  taxInstallments?: NumericInput;
   290	  otherObligations?: NumericInput;
   291	};
   292	
   293	export function calculateLiquidityCoverage(periods: readonly LiquidityPeriod[]) {
   294	  let priorClosing: Decimal | null = null;
   295	  return periods.map((period) => {
   296	    const opening = priorClosing ?? decimal(period.openingCash);
   297	    const sources = opening.plus(period.cfads).plus(period.contractedSources ?? 0);
   298	    const service = decimal(period.principal)
   299	      .plus(period.interest)
   300	      .plus(period.leases ?? 0)
   301	      .plus(period.taxInstallments ?? 0)
   302	      .plus(period.otherObligations ?? 0);
   303	    const closing = sources.minus(service);
   304	    priorClosing = closing;
   305	    return {
   306	      period: period.period,
   307	      openingCash: canonical(opening),
   308	      sources: canonical(sources),
   309	      debtService: canonical(service),
   310	      coverage: service.isZero() ? null : canonical(sources.div(service)),
   311	      closingCash: canonical(closing),
   312	      deficit: canonical(Decimal.max(closing.negated(), 0)),
   313	    };
   314	  });
   315	}
