   317	export function applyRateShock(input: {
   318	  averageBalance: NumericInput;
   319	  baseRate: NumericInput;
   320	  shock: NumericInput;
   321	  hedgeOffset?: NumericInput;
   322	}): {baseInterest: string; stressedInterest: string; delta: string} {
   323	  const balance = decimal(input.averageBalance);
   324	  const baseInterest = balance.mul(input.baseRate);
   325	  const stressedInterest = balance.mul(decimal(input.baseRate).plus(input.shock)).minus(input.hedgeOffset ?? 0);
   326	  return {
   327	    baseInterest: canonical(baseInterest),
   328	    stressedInterest: canonical(stressedInterest),
   329	    delta: canonical(stressedInterest.minus(baseInterest)),
   330	  };
   331	}
